mapper.select:
SELECT item.id, item.asn_id, item.asn_no, item.item_no, item.business_item_no, item.business_form_type, item.category_code, item.category_name, item.sku_code, item.sku_name, item.batch_no, item.factory, item.inventory_area, item.primary_qty, item.primary_unit, item.auxiliary_qty, item.auxiliary_unit, item.confirm_qty, item.submit_qty, item.plan_delivery_date, item.quality_flag, item.package_type, asn.business_form_no FROM wms_asn_item item INNER JOIN wms_asn asn ON item.asn_id = asn.id
AND item.asn_id = #{param.asnId}
AND item.asn_no = #{param.asnNo}
AND item.sku_code = #{param.skuCode}
AND item.batch_no = #{param.batchNo}
AND item.business_item_no LIKE CONCAT('%', #{param.businessItemNo}, '%')
AND asn.business_form_no LIKE CONCAT('%', #{param.businessOrderNo}, '%')
AND asn.asn_status IN
#{status}
AND asn.asn_status = #{param.asnStatus}
AND asn.supplier_code = #{param.supplierCode}
AND asn.create_datetime >= #{param.createTimeStart}
AND asn.create_datetime < #{param.createTimeEnd}
ORDER BY asn.create_datetime DESC, item.item_no
